sys_script.script:
(function executeRule(current, previous /*null when async*/) {
if (current.isNewRecord()) {
        var caseId = current.case_id; // Replace with your field name
        if (!caseId) {
            return; // Exit if no case_id is provided
        }

        // Query the table for the latest matching record by case_id
        var gr = new GlideRecord(current.getTableName()); // Adjust table if needed
        gr.addQuery('case_id', caseId);
        gr.orderByDesc('sys_created_on'); // Sort by most recent
        gr.setLimit(1); // Fetch only the latest record
        gr.query();

        if (gr.next()) {
            // Dynamically copy all fields from gr to current
            var fieldsToSkip = ['sys_id', 'sys_created_by', 'sys_created_on', 'sys_updated_by', 'sys_updated_on'];

            // Iterate through all fields in the `current` object
            var fieldNames = Object.keys(current);
            fieldNames.forEach(function (fieldName) {
                if (!fieldsToSkip.includes(fieldName) && gr.isValidField(fieldName)) {
                    current.setValue(fieldName, gr.getValue(fieldName));
                }
            });
        }
		gs.addErrorMessage('success')
    }
})(current, previous);
